import{_ as i,o as a,c as t,a3 as r}from"./chunks/framework.1Y430-yj.js";const h=JSON.parse('{"title":"1.5 Automatic Maximum Gross Production","description":"","frontmatter":{"lang":"en-US","translationSource":{"title":"1\\\\.5智能最大毛产","archivedAt":"2026-10-23T14:20:34.857Z","url":"https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=umMgUzRULECbKVLsX5rOlZ","scope":"page"}},"headers":[],"relativePath":"logistics/src/page-umMgUzRULECbKVLsX5rOlZ.md","filePath":"logistics/src/page-umMgUzRULECbKVLsX5rOlZ.md","lastUpdated":null}'),n={name:"logistics/src/page-umMgUzRULECbKVLsX5rOlZ.md"};function o(s,e,l,u,p,c){return a(),t("div",null,[...e[0]||(e[0]=[r('<div class="logistics-content"><span class="logistics-source-anchor" id="_1-5智能最大毛产" aria-hidden="true"></span><h1 id="_1-5-automatic-maximum-gross-production" tabindex="-1">1.5 Automatic Maximum Gross Production <a class="header-anchor" href="#_1-5-automatic-maximum-gross-production" aria-label="Permalink to &quot;1\\.5 Automatic Maximum Gross Production&quot;">​</a></h1><blockquote><p>Source page ID: <code>umMgUzRULECbKVLsX5rOlZ</code> ｜ <a href="https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=umMgUzRULECbKVLsX5rOlZ" target="_blank" rel="noreferrer">Open in Tencent Docs</a></p></blockquote><p>Video links<br> The production line itself: <a href="https://www.bilibili.com/video/BV1tgbW6RE6W/?share_source=copy_web&amp;vd_source=9f60c330d7b703cb7375642cd8db2daf" target="_blank" rel="noreferrer">https://www.bilibili.com/video/BV1tgbW6RE6W/?share_source=copy_web&amp;vd_source=9f60c330d7b703cb7375642cd8db2daf</a><br> Adaptive-operation explanation:<br> Automatic-balancing explanation:</p><p><a href="https://zmdjj.pythonanywhere.com/" target="_blank" rel="noreferrer">A website for reading this page, made by a group member</a>. People answering questions can refer to sections there, avoiding the problem where Tencent Docs occasionally misbehaves and every link redirects to the Introduction to Endfield Logistics Bugs subpage.</p><p><span id="source-block-M4g2iTuaxVbrNLXFtNtyLJ"></span></p><span class="logistics-source-anchor" id="_1-5智能最大毛产出基建蓝图" aria-hidden="true"></span><h2 id="_1-5-automatic-maximum-gross-production-factory-blueprints" tabindex="-1">1.5 Automatic Maximum Gross Production Factory Blueprints <a class="header-anchor" href="#_1-5-automatic-maximum-gross-production-factory-blueprints" aria-label="Permalink to &quot;1.5 Automatic Maximum Gross Production Factory Blueprints&quot;">​</a></h2><p><span class="mark-red"><strong>Scroll down for troubleshooting and extended functions.<br> If you ask a question that can be answered directly by</strong></span> <a href="./page-umMgUzRULECbKVLsX5rOlZ#source-block-yDRC0KVhKSyTDPUKCagyWK">1.5 Automatic Maximum Gross Production</a><span class="mark-red"><strong>, your question will very likely be ignored.</strong></span></p><p><span class="mark-red"><strong>For any other requirements, ask Tencent Docs&#39; AI reader, or read the table of contents before asking group members. On a computer it is on the left; on mobile, open it manually from the document&#39;s upper-right corner.</strong></span></p><p><span id="source-block-bmoqVFuDdN4lBYeIp0H6bn"></span></p><span class="logistics-source-anchor" id="蓝图更新记录" aria-hidden="true"></span><h3 id="blueprint-update-record" tabindex="-1">Blueprint Update Record <a class="header-anchor" href="#blueprint-update-record" aria-label="Permalink to &quot;Blueprint Update Record&quot;">​</a></h3><ul><li><p>2026.9.7 13:49: Updated blueprint: Wuling 05.</p></li><li><p><span class="mark-grey"><s>2026.9.8 00:26: Updated blueprints: Yinglung Pass 01 and Yinglung Pass 03 (ineffective update).</s></span></p></li><li><p>2026.9.15 2:56: Updated blueprints: Yinglung Pass (all).</p></li><li><p>2026.9.16 0:57: Updated blueprints: Jingyu Valley (all).</p></li><li><p>2026.9.21: Updated blueprints: Chubby Lung phase two.</p></li></ul><p>The updated codes are in the corresponding regional sections below. See <a href="./page-umMgUzRULECbKVLsX5rOlZ#source-block-kK6NOYj9oOxPhfdKLYWdO5">1.5 Automatic Maximum Gross Production</a> for update details.</p><p><span id="source-block-GPl9UvYR9IrVP89xMoefeT"></span></p><span class="logistics-source-anchor" id="蓝图准备工作" aria-hidden="true"></span><h3 id="blueprint-preparations" tabindex="-1"><strong>Blueprint Preparations</strong> <a class="header-anchor" href="#blueprint-preparations" aria-label="Permalink to &quot;**Blueprint Preparations**&quot;">​</a></h3><p><strong>Check your stored materials:</strong></p><p><span class="mark-red">10000+ Xiranite, 10000+ Cuprium, 2000+ Cuprium Part, 1000+ Amethyst Part, 1000+ Ferrium Part, 1000+ Origocrust, 1000+ Originium Ore, 500+ Jincao, 500+ Yazhen, 500+ Sandleaf Seed.<br></span>Also, <span class="mark-red">Pyrrolite storage must not be full.</span></p><p><em>P.S. Valley and Wuling storage are shared when crafting facilities.</em></p><p><strong>Check your base upgrades:</strong></p><p>We recommend <span class="mark-red">maxing out every area expansion and Depot Bus Section upgrade</span> (in fact, Marker Stone and Yinglung Pass can each do without the last two bus upgrades). You must <span class="mark-red">unlock every technology except the turrets</span>. Some technologies <span class="mark-red">have prerequisite quests</span>; complete any missing prerequisites yourself.</p><p><strong>Check the North Wuling Exclusion Zone&#39;s</strong> <span class="mark-red"><strong>Xiragen vents</strong></span><strong>:</strong></p><p>You need to deliver <span class="mark-red">80+ Xiragen/min, equivalent to at least 4 high-purity deposits</span>, to the Xiranflow Cloudseeder base at Yinglung.</p><p><strong>Also note the following when placing blueprints:</strong></p><ul><li><p>Before placing the next blueprint, <span class="mark-red">finish constructing every facility in the previous one: craft and submit the facilities; they must not remain yellow construction ghosts.</span></p></li><li><p>Do not make any changes inside these production lines beyond those demonstrated in the video.</p></li></ul><p>If you do not have enough Cuprium Part in storage, consider this blueprint:</p><p>Arknights: Endfield blueprint [Cuprium Part Preparation], sharing code EF012UOAUUI4O8UAeIOo. Copy it and use it in the game.</p><p><span class="mark-grey">Connect two Fluid Pumps to this blueprint. It produces 120 Cuprium Part/min. (Keep the power on~)</span></p><p><span id="source-block-aZli93Lno95jxDGgn1OJj9"></span></p><span class="logistics-source-anchor" id="应龙-自动赫灼18灼" aria-hidden="true"></span><span class="logistics-source-anchor" id="yinglong-automatic-hetonite-pyrrolite-18-pyrrolite-parts" aria-hidden="true"></span><h3 id="yinglung-automatic-hetonite-pyrrolite-18-pyrrolite-parts" tabindex="-1">Yinglung: Automatic Hetonite/Pyrrolite, 18 Pyrrolite Parts <a class="header-anchor" href="#yinglung-automatic-hetonite-pyrrolite-18-pyrrolite-parts" aria-label="Permalink to &quot;Yinglung: Automatic Hetonite/Pyrrolite, 18 Pyrrolite Parts&quot;">​</a></h3><p><img src="/endfield-logistics-wiki/logistics/src/assets/images/img-6c42221152df9dc3.q90-c93ab1aa4e5d85b5.webp" alt="15 Automatic Maximum Gross Production"></p><p>Arknights: Endfield blueprint [Yinglung Unpowered Crucible], sharing code EF01ao68oo706A06oe5e. Copy it and use it in the game.<br><span class="mark-blue">Once the Reactor Crucible is prepared—containing one each of Clean Water, Originium Ore, Ferrium Ore, Cuprium Ore, and Cuprium Part—move it to an open space and delete the rest of the structure. After placing Yinglung 01, replace the unpowered crucible in 01 with the prepared one.</span></p><p>Arknights: Endfield blueprint [Yinglung 01], sharing code EF0193au33A6ae1a5UI2. Copy it and use it in the game.</p><p><span class="mark-blue">Connect all conduits; use the image below as a reference.</span></p><p>Arknights: Endfield blueprint [Yinglung 02], sharing code EF01u284221I80IOAoOU. Copy it and use it in the game.</p><p>Arknights: Endfield blueprint [Yinglung 03], sharing code EF01081388U91i4uE179. Copy it and use it in the game.</p><p>Major update: <span class="mark-red">2026.9.15 2:56: Rebuilt the entire Yinglung base to fix the automatic Hetonite/Pyrrolite switching bug.</span></p><p>If you have installed the old blueprints, make these changes:</p><ul><li><p>Follow the conduits&#39; connection process in the video, moving each conduit connected to the outside out of the base, then delete the old Yinglung base.</p></li><li><p>When deleting the old base, <span class="mark-red">do not keep</span> the unpowered crucible; <span class="mark-red">prepare it again from scratch.</span></p></li><li><p>Before replacing the blueprints, ensure you have 500+ Xiranite in storage and neither Hetonite nor Pyrrolite storage is full. If you have no Xiranite, follow <a href="./page-umMgUzRULECbKVLsX5rOlZ#source-block-sdvd1X3RJrhAL32oIkexUc">1.5 Automatic Maximum Gross Production</a>. If Hetonite and Pyrrolite storage are full, consume 500+ Hetonite Part and Pyrrolite Part.</p></li><li><p>The new conduits and unpowered crucible occupy essentially the same positions as in the old version.</p></li><li><p>For replacement guidance, see <a href="https://www.bilibili.com/video/BV1xZeF6PEAj/?vd_source=673daf93e07b6287b53c46b17964ca5b#reply314160488385" target="_blank" rel="noreferrer">Endfield 1.5: Copy with Care—Integrated Aid Chubby Lung Patch! Finish Both Phases at Once! — bilibili</a>.</p></li></ul><p><span class="mark-grey"><em>Why stress connecting a single-port conduit to a manifold? A manifold-to-manifold connection allows 2–4/s liquid/gas transport, whereas the “conduit manifold–Pipe Converger” priority structure sends the portion above 2/s into the lower-priority pipe. Its priority is therefore incomplete. For example, suppose a manifold-to-manifold connection carries “1/s for 1s, 2/s for 1s, 3/s for 1s.” The average flow is 2/s, so ideally nothing should enter the lower-priority pipe of that structure. In practice, during “3/s for 1s,” 2/s goes into the priority pipe and 1/s into the lower-priority pipe for that 1s. The lower-priority pipe unexpectedly receives an average of 1/3/s! Connecting a single-port conduit to a manifold directly caps the rate at 2/s, making this priority structure complete.</em></span></p><p><img src="/endfield-logistics-wiki/logistics/src/assets/images/img-4e286bc5922f1d90.q90-f49b6c0492282133.webp" alt="15 Automatic Maximum Gross Production"></p><p><img src="/endfield-logistics-wiki/logistics/src/assets/images/img-ebaa20e4ccef4279.jpeg" alt="15 Automatic Maximum Gross Production"></p><p><span id="source-block-twa6LIcdMfCj7nW2vtdGKB"></span></p><span class="logistics-source-anchor" id="武陵-7池6液气兼容中电爆仓稳态" aria-hidden="true"></span><h3 id="wuling-7-crucibles-6-fluid-gas-transmuters-compatible-with-full-sc-wuling-battery-storage" tabindex="-1">Wuling: 7 Crucibles, 6 Fluid-Gas Transmuters, Compatible with Full SC Wuling Battery Storage <a class="header-anchor" href="#wuling-7-crucibles-6-fluid-gas-transmuters-compatible-with-full-sc-wuling-battery-storage" aria-label="Permalink to &quot;Wuling: 7 Crucibles, 6 Fluid-Gas Transmuters, Compatible with Full SC Wuling Battery Storage&quot;">​</a></h3><p><img src="/endfield-logistics-wiki/logistics/src/assets/images/img-72bd09479c37b968.jpeg" alt="15 Automatic Maximum Gross Production"></p><p>Arknights: Endfield blueprint [Wuling 01], sharing code EF0170i9002Ui521O0Ai. Copy it and use it in the game.</p><p><span class="mark-blue">After placing 01, configure the PAC&#39;s Depot Unloaders according to the control ports.</span></p><p>Arknights: Endfield blueprint [Wuling 02], sharing code EF014AEiAAo5E34OE71A. Copy it and use it in the game.</p><p>Arknights: Endfield blueprint [Wuling 03], sharing code EF01E75U77u25o8o3uIa. Copy it and use it in the game.</p><p>Arknights: Endfield blueprint [Wuling 04], sharing code EF01081388U91ieIE179. Copy it and use it in the game.</p><p>Arknights: Endfield blueprint [Wuling 05], sharing code EF016u0Iuui1078uOa3e. Copy it and use it in the game. <span class="mark-red">Updated this blueprint (05) on 2026.9.7 13:49. See the update log below; replacing the blueprint is unnecessary.</span></p><p>Arknights: Endfield blueprint [Wuling 06], sharing code EF01A671665i7EAu91eO. Copy it and use it in the game.</p><p><span class="mark-blue">If you are connecting the Purification Node or a Yinglung–Wuling Xiragen supply, connect the conduits as shown below. If you are not using the Purification Node, remember to add Sewage treatment yourself. Choose one of these two blueprints for your situation.</span></p><p>Arknights: Endfield blueprint [Purified Water Conduit Connection], sharing code EF01u28U5Ie8701AoOU. Copy it and use it in the game.</p><p>Arknights: Endfield blueprint [Without the Water-Purification Node], sharing code EF01u28U5Ie870oAoOU. Copy it and use it in the game.</p><p><img src="/endfield-logistics-wiki/logistics/src/assets/images/img-1e4e6161266364ef.q90-fcc78a4d33db5f2e.webp" alt="15 Automatic Maximum Gross Production"></p><p><img src="/endfield-logistics-wiki/logistics/src/assets/images/img-a3dc4152d91d1c49.jpeg" alt="15 Automatic Maximum Gross Production"></p><p><span id="source-block-qMT4GtWsR8rDPnonIh5VLq"></span></p><span class="logistics-source-anchor" id="景玉-12息壤2中电" aria-hidden="true"></span><h3 id="jingyu-12-xiranite-2-sc-wuling-batteries" tabindex="-1">Jingyu: 12 Xiranite, 2 SC Wuling Batteries <a class="header-anchor" href="#jingyu-12-xiranite-2-sc-wuling-batteries" aria-label="Permalink to &quot;Jingyu: 12 Xiranite, 2 SC Wuling Batteries&quot;">​</a></h3><p><img src="/endfield-logistics-wiki/logistics/src/assets/images/img-585d88628da76e7b.jpeg" alt="15 Automatic Maximum Gross Production"></p><p>Arknights: Endfield blueprint [Jingyu 01], sharing code EF018OIEOO93I18uUI73. Copy it and use it in the game.</p><p><span class="mark-blue">After placing 01, configure the PAC&#39;s Depot Unloaders according to the control ports.</span></p><p>Arknights: Endfield blueprint [Jingyu 02], sharing code EF01081388U91i6IE179. Copy it and use it in the game. (<span class="mark-red">Before 2026.9.16 11:28, the control port ahead of the Inergen disperser was not rate-limited.</span> If you copied it earlier, change it yourself or replace the blueprint.)</p><p><span class="mark-blue">After placing 02, connect Inergen/Clean Water. Connect one Fluid Pump to each Clean Water control port, and one or more gas vents to the Inergen control port.</span></p><p>Major update: <span class="mark-red">2026.9.15 2:56: Rebuilt the entire Jingyu Valley base.</span></p><p><span class="mark-grey">The new base greatly reduces the likelihood of various failures to maintain Xiranite oversupply. Essentially, some Xiranite was previously deposited through Depot Loaders; it is now deposited through Protocol Stashes, so the unloaders mostly service their outputs round-robin and maintain the oversupply. Water/Inergen now enter through exposed pipes, reducing copying mistakes.</span></p><p>If you have installed the old blueprints, you can modify them as follows:</p><p><span class="mark-grey">(If your factory report is correct and there are no anomalies, you do not have to change it.)</span></p><ul><li><p>Move the water and Inergen from the single-port Conduit Outlets to the base&#39;s edge for later use, then delete the old Jingyu Valley base.</p></li><li><p>Remove the old conduit manifolds. Clean Water and Inergen will use exposed pipes instead.</p></li><li><p>Before replacing the blueprints, ensure you have 500+ Jincao and Sandleaf Seed, plus 1000+ Xiranite in storage, to prevent the Xircon line from breaking due to Xiranite starvation during reconstruction. If Xiranite storage is exhausted, see <a href="./page-umMgUzRULECbKVLsX5rOlZ#source-block-sdvd1X3RJrhAL32oIkexUc">1.5 Automatic Maximum Gross Production</a>. Since the Xiranite line must be demolished and rebuilt, Xiranite may fall seriously short of demand. After rebuilding Jingyu Valley, you can repair the main base&#39;s Xircon line according to <a href="./page-umMgUzRULECbKVLsX5rOlZ#source-block-sdvd1X3RJrhAL32oIkexUc">1.5 Automatic Maximum Gross Production</a>.</p></li><li><p>For replacement guidance, see <a href="https://www.bilibili.com/video/BV1xZeF6PEAj/?vd_source=673daf93e07b6287b53c46b17964ca5b#reply314160488385" target="_blank" rel="noreferrer">Endfield 1.5: Copy with Care—Integrated Aid Chubby Lung Patch! Finish Both Phases at Once! — bilibili</a>.</p></li></ul><p><span id="source-block-bV0Hdv0wVPjL7qIf7R1aEm"></span></p><span class="logistics-source-anchor" id="首墩插件" aria-hidden="true"></span><span class="logistics-source-anchor" id="shoudun-add-on" aria-hidden="true"></span><h3 id="marker-stone-add-on" tabindex="-1">Marker Stone Add-On <a class="header-anchor" href="#marker-stone-add-on" aria-label="Permalink to &quot;Marker Stone Add-On&quot;">​</a></h3><p>Arknights: Endfield blueprint [Cuprium Part Preparation], sharing code EF012UOAUUI4O8UAeIOo. Copy it and use it in the game.</p><p><span class="mark-grey">Use it if you find you lack Cuprium Part before or while placing the blueprints.</span></p><p>Choose either of the following two blueprints:</p><p>Arknights: Endfield blueprint [Marker Stone with Stashes], sharing code EF01eaA0aaE7A412o9i8. Copy it and use it in the game.</p><p><span class="mark-grey">Slightly smaller footprint; consumes extra power for the stashes.</span></p><p>Arknights: Endfield blueprint [Marker Stone without Stashes], sharing code EF013Eo74uioeau90579. Copy it and use it in the game..</p><p><span class="mark-grey">Slightly larger footprint; saves the stashes&#39; power.</span></p><p><span id="source-block-0sNX0wBVHLjwM9Rp2FzvjJ"></span></p><span class="logistics-source-anchor" id="龙泡泡插件" aria-hidden="true"></span><h3 id="chubby-lung-add-on" tabindex="-1">Chubby Lung Add-On <a class="header-anchor" href="#chubby-lung-add-on" aria-label="Permalink to &quot;Chubby Lung Add-On&quot;">​</a></h3><p><span id="source-block-md1ZBjonVneH9c7Z1UVSH4"></span></p><span class="logistics-source-anchor" id="一阶段-主基地-首墩-6-min息壤龙泡泡" aria-hidden="true"></span><span class="logistics-source-anchor" id="phase-one-main-base-shoudun-6-xiranite-chubby-lung-min" aria-hidden="true"></span><h4 id="phase-one-main-base-marker-stone-6-xiranite-chubby-lung-min" tabindex="-1">Phase One: Main Base/Marker Stone, 6 Xiranite Chubby Lung/min <a class="header-anchor" href="#phase-one-main-base-marker-stone-6-xiranite-chubby-lung-min" aria-label="Permalink to &quot;Phase One: Main Base/Marker Stone, 6 Xiranite Chubby Lung/min&quot;">​</a></h4><p><img src="/endfield-logistics-wiki/logistics/src/assets/images/img-d998b8c45e664f7a.q90-0228a8a7d382f57e.webp" alt="15 Automatic Maximum Gross Production"></p><p>For installation, see <a href="https://www.bilibili.com/video/BV1xZeF6PEAj/?vd_source=673daf93e07b6287b53c46b17964ca5b#reply314160488385" target="_blank" rel="noreferrer">Endfield 1.5: Copy with Care—Integrated Aid Chubby Lung Patch! Finish Both Phases at Once! — bilibili</a>.</p><p>You can put it in an open area at either the main base or Marker Stone.</p><p><span class="mark-red">Because Cuprium oversupply may be insufficient, follow</span> <a href="./page-umMgUzRULECbKVLsX5rOlZ#source-block-sdvd1X3RJrhAL32oIkexUc">1.5 Automatic Maximum Gross Production</a><span class="mark-red"> and turn off three Shredding Units. (If you want Cuprium to accumulate and completely avoid insufficient oversupply, consider turning off more; that is in fact what</span> <a href="./page-umMgUzRULECbKVLsX5rOlZ#source-block-6rcRwbuFHgJ50Hq0nLJmk8">1.5 Automatic Maximum Gross Production</a><span class="mark-red"> describes.) Because insufficient Xiranite oversupply can break the Xircon line, follow</span> <a href="./page-umMgUzRULECbKVLsX5rOlZ#source-block-sdvd1X3RJrhAL32oIkexUc">1.5 Automatic Maximum Gross Production</a><span class="mark-red"> and turn off four Reactor Crucibles.</span></p><p>Arknights: Endfield blueprint [Phase One 01], sharing code EF016u0Iuui10762O83e. Copy it and use it in the game.</p><p><span class="mark-blue">Tested in actual operation and working normally.</span></p><p><span id="source-block-Sp48AHGvwvLIbjxO4OoUeX"></span></p><span class="logistics-source-anchor" id="二阶段-首墩-7-5-min重息壤龙泡泡" aria-hidden="true"></span><span class="logistics-source-anchor" id="phase-two-shoudun-7-5-heavy-xiranite-chubby-lung-min" aria-hidden="true"></span><h4 id="phase-two-marker-stone-7-5-heavy-xiranite-chubby-lung-min" tabindex="-1">Phase Two: Marker Stone, 7.5 Heavy Xiranite Chubby Lung/min <a class="header-anchor" href="#phase-two-marker-stone-7-5-heavy-xiranite-chubby-lung-min" aria-label="Permalink to &quot;Phase Two: Marker Stone, 7.5 Heavy Xiranite Chubby Lung/min&quot;">​</a></h4><p>Last updated: September 21.</p><p><span class="mark-blue">Tested in actual operation and working normally.</span></p><p><span class="mark-red"><strong>!!! Many people cannot even ensure normal phase-one output. Phase two draws on more inputs and places a heavier load on the original lines. If you still cannot troubleshoot before using the phase-two blueprints, you may fail to redeem all 50,000 T-Creds (5w) in the event shop. There is still time to switch to other blueprints. Take responsibility for your own account!!!</strong></span></p><p><strong>That said, if you ignore that trivial 50,000 T-Creds (5w), 6 Heavy Xiranite Chubby Lung/min and 0 Xiranite Chubby Lung/min are actually enough for the other exchanges. Decide for yourself.</strong></p><p><img src="/endfield-logistics-wiki/logistics/src/assets/images/img-fca454156743051e.jpeg" alt="15 Automatic Maximum Gross Production"></p><p><span class="mark-grey"><em>Phase two has not opened and its recipes have not unlocked. Of course copying this before then produces nothing! If you have copied it and do not want to demolish it, switch it off; it will quietly eat 36 Xiranite/min. Phase two unlocks September 22.</em></span></p><p>For installation, see <a href="https://www.bilibili.com/video/BV1xZeF6PEAj/?vd_source=673daf93e07b6287b53c46b17964ca5b#reply314160488385" target="_blank" rel="noreferrer">Endfield 1.5: Copy with Care—Integrated Aid Chubby Lung Patch! Finish Both Phases at Once! — bilibili</a>.</p><p>Marker Stone must be replaced because its Inergen supply needs integrating. Move the connected Inergen conduit out of the base first. In other words, insufficient Inergen is why this cannot simply be placed as an add-on.</p><p>Likewise, insufficient Inergen makes further phase-two Chubby Lung expansion difficult. Keep the main base&#39;s 6/min phase-one line to clear the event shop. <strong>However, if you ignore that trivial 50,000 T-Creds (5w) in the shop, 6 Heavy Xiranite Chubby Lung/min and 0 Xiranite Chubby Lung/min are enough for the other exchanges. Thus keeping the phase-one line is not mandatory, and without it the loss of oversupply is less severe than described below. (This bold white-text paragraph was added 2026.9.23 4:26.)</strong></p><p><span class="mark-red">Because Cuprium oversupply may be insufficient, follow</span> <a href="./page-umMgUzRULECbKVLsX5rOlZ#source-block-sdvd1X3RJrhAL32oIkexUc">1.5 Automatic Maximum Gross Production</a><span class="mark-red"> and turn off</span> <span class="mark-red"><u><strong>six</strong></u></span><span class="mark-red"> Shredding Units</span><span class="mark-red"><strong> (eight if Xiranite storage is empty but Cuprium storage is not)</strong></span><span class="mark-red">. (If you want Cuprium to accumulate to completely avoid insufficient oversupply, consider turning off more; that is in fact what</span> <a href="./page-umMgUzRULECbKVLsX5rOlZ#source-block-6rcRwbuFHgJ50Hq0nLJmk8">1.5 Automatic Maximum Gross Production</a><span class="mark-red"> describes.) Because insufficient Xiranite oversupply will break the Xircon line, follow</span> <a href="./page-umMgUzRULECbKVLsX5rOlZ#source-block-sdvd1X3RJrhAL32oIkexUc">1.5 Automatic Maximum Gross Production</a><span class="mark-red"> and turn off</span> <span class="mark-red"><u><strong>four</strong></u></span><span class="mark-red"> Reactor Crucibles.</span></p><p><span class="mark-red"><strong>If the Xircon line still loses Xiranite oversupply, replace Jingyu Valley with the September 15 update. If already updated, turn off more Cuprium Shredding Units. For a more drastic and reliable measure, see</strong></span> <a href="./page-umMgUzRULECbKVLsX5rOlZ#source-block-b0yB7GcYPo8AVeFqRmsf5g">1.5 Automatic Maximum Gross Production</a>.</p><p><span class="mark-blue"><strong>Also, during the Chubby Lung event only, consider turning off one Heavy Xiranite Solid-Gas Transmuting Unit at the main base.</strong></span></p><p><span class="mark-grey">If Heavy Xiranite storage is already full, however, losing Xiranite oversupply is essentially impossible.</span></p><p>Arknights: Endfield blueprint [Phase Two 01], sharing code EF01081388U91i6eE179. Copy it and use it in the game. Updated September 21 after correcting the recipes.</p><p><span class="mark-grey">Place flush against the southwest corner. Connect water, acid, and Inergen according to the control-port labels: one pipe per water or acid pump, but two gas vents per Inergen pipe. Wait until the crucible starts producing Liquid Xiranite before placing 02.</span></p><p>Arknights: Endfield blueprint [Phase Two 02], sharing code EF015i2eii8O2u55eIoe. Copy it and use it in the game. Updated September 21 after correcting the recipes.</p><p><span class="mark-grey">Fit it into 01.</span></p><p><span class="mark-blue">Blueprint maintenance tip: a possible fault is the second Fluid-Gas Transmuting Unit counted east to west, because it mixes Xiranite and Cuprium. Normally, if you wait long enough after placing 01—until 01 produces Liquid Xiranite—before placing 02, it will not fail at all. If it nevertheless fails for some reason, manually remove the 1 Cuprium Solution stuck in this unit&#39;s input slots.</span></p><p><span class="mark-red">Some warm-up time is normally required. If the line has been placed and recipes unlocked but it is still not producing after 10 minutes, something is wrong.</span></p><p><img src="/endfield-logistics-wiki/logistics/src/assets/images/img-a8a378d4c7edcd5c.q90-8bae6ab08a2f6d95.webp" alt="15 Automatic Maximum Gross Production"></p><p><img src="/endfield-logistics-wiki/logistics/src/assets/images/img-149d1ec1ed2b9c52.q90-25d7473d97238e3a.webp" alt="15 Automatic Maximum Gross Production"></p><p><span id="source-block-Uv3fH2ncTMOWEtYds9hNwm"></span></p><span class="logistics-source-anchor" id="停止灼铜-赫铜生产-进阶内容" aria-hidden="true"></span><h4 id="stop-pyrrolite-hetonite-production-advanced" tabindex="-1">Stop Pyrrolite/Hetonite Production (Advanced) <a class="header-anchor" href="#stop-pyrrolite-hetonite-production-advanced" aria-label="Permalink to &quot;Stop Pyrrolite/Hetonite Production (Advanced)&quot;">​</a></h4><p>You can then add many Chubby Lung lines to consume the inputs previously used for Pyrrolite/Hetonite, instead of running only the 6/min phase-one line or 7.5/min phase-two line demonstrated in <a href="https://www.bilibili.com/video/BV1xZeF6PEAj/?vd_source=673daf93e07b6287b53c46b17964ca5b#reply314160488385" target="_blank" rel="noreferrer">Endfield 1.5: Copy with Care—Integrated Aid Chubby Lung Patch! Finish Both Phases at Once! — bilibili</a>.</p><p><span class="mark-blue"><strong>The picture below forgot to mention: after turning off Yinglung, the main base and Marker Stone still keep making powder. Turn off those Shredding Units too, or you will have to sit waiting for Cuprium Powder storage to fill.</strong></span></p><p><img src="/endfield-logistics-wiki/logistics/src/assets/images/img-f7d725a9d4a73fbb.q90-b3f500f1a9fdcd9f.webp" alt="15 Automatic Maximum Gross Production"></p><p>(When looking at the next picture, remember the small Chubby Lung line at the main base.) We now make Chubby Lung the final Cuprium sink. Supply Xiranite and Heavy Xiranite fully, letting the Chubby Lung lines consume the Cuprium left over by Heavy Xiranite: oversupply Xiranite and Heavy Xiranite, but not Cuprium. (Heavy Xiranite is used by the phase-two recipe; since it has stored reserves, supplying the normal number of unloaders already counts as oversupply.) <strong>In fact, simply delete half the Cuprium unloaders so each remaining unloader serves one Fitting Unit:</strong></p><p><img src="/endfield-logistics-wiki/logistics/src/assets/images/img-e7793617068a6faf.q90-9c45a18d6e67943c.webp" alt="15 Automatic Maximum Gross Production"></p><p>Use this blueprint code if needed <strong>(we recommend waiting until Separator Core/Xircon storage is full; otherwise place one fewer line)</strong>:<br> Arknights: Endfield blueprint [Xiranite Chubby Lung!?], sharing code EF01ao68oo706A933oe5e. Copy it and use it in the game.</p><p><span class="mark-red">A rather bizarre result: the final balanced output is 14.75 SC Wuling Battery, 2.3125 Yazhen Syringe [C], 26.758 Heavy Xiranite, and 22.155 Xiranite Chubby Lung. Converting the Xiranite Chubby Lung to vouchers already exceeds 老乡&#39;s total voucher output (2215.5&gt;2036)... Consider switching off one line, which accelerates Heavy Xiranite and allows some Cuprium to accumulate.</span></p><p><span class="mark-grey">After using it, the author feels turning off one line is better (I turned off the main-base one). Otherwise a loss of Xiranite oversupply is awkward to fix, and apart from filling storage faster, I feel there is not much difference anyway () Also, what is this design, yj? You can force the Chubby Lung exchange without vouchers, but if you do not want to do that, you have to watch out yourself and avoid exchanging away all the vouchers ()</span></p><p><span class="mark-grey">Making more Chubby Lung really feels like a mistake. When Pyrrolite/Hetonite storage fills, I can still build turrets. After exchanging Chubby Lung for vouchers and filling Heavy Xiranite storage, what else can I do? ((</span></p><p><span id="source-block-XjBQl3qROfHLoRb49jWuJy"></span></p><span class="logistics-source-anchor" id="全自动切换阶段" aria-hidden="true"></span><h4 id="fully-automatic-phase-switching" tabindex="-1">Fully Automatic Phase Switching <a class="header-anchor" href="#fully-automatic-phase-switching" aria-label="Permalink to &quot;Fully Automatic Phase Switching&quot;">​</a></h4><p><span class="mark-grey">Creating the folder; please wait for future updates...</span></p><p><span id="source-block-yDRC0KVhKSyTDPUKCagyWK"></span></p><span class="logistics-source-anchor" id="常见问题汇总" aria-hidden="true"></span><h2 id="frequently-asked-questions" tabindex="-1">Frequently Asked Questions <a class="header-anchor" href="#frequently-asked-questions" aria-label="Permalink to &quot;Frequently Asked Questions&quot;">​</a></h2><p><span class="mark-red">Most problems can be fixed by replacing the production lines. For a more precise approach, see “Warm-Up” below.</span></p><p><span class="mark-red"><strong>!!! Do not place the next blueprint while facilities from the previous blueprint are unfinished yellow construction ghosts. Craft and submit the facilities first, or the priority structure will break!!!</strong></span></p><p><span class="mark-red"><strong>!!! Do not make changes inside these production lines beyond those demonstrated in the video!!!</strong></span></p><p><span class="mark-blue">When posting a production report in the group or bilibili comments for troubleshooting, always show these items. You can star items in the report to pin them for easy viewing:<br> Originium Ore, Ferrium Ore, Cuprium Ore, Cuprium, Ferrium Powder, Cuprium Powder, Dense Originium Powder, Hetonite, Xiranite, Heavy Xiranite, Xircon, Pyrrolite, Separator Core, Cuprium Solution, Cuprium Gas, Hetonite Gas, Pyrrolite Gas, SC Wuling Battery (default ordering, ascending).</span></p><p><span class="mark-blue"><strong>If you do not follow this, we may well ignore your question.</strong></span></p><ol><li><p>The Jingyu Valley blueprint will not fit: watch the tutorial carefully and move the conduits as demonstrated. Move each Conduit Inlet entirely outside the base boundary. Check for dropped items inside the base (rare).</p></li><li><p>Yinglung Pass hits the pipe-component limit: replace the acid conduit with a manifold and remove its Pipe Converger; do the same for the Inergen vents. Check whether you placed many pipe components as position markers at the essence-farming location.</p></li><li><p>Fluctuations in the production report are normal: adaptive lines oscillate extensively to control reaction rates automatically. Do not panic. Machines switching on and off are normal too; this oscillating adaptive input supply avoids wasting any Xiranite, which is why our output is so high. For the device details, see <a href="./page-kXUgC0EOTqKh09bVHL9EPN">Some Simpler Adaptive Setups</a>.</p></li><li><p>Consumption exceeding production for Xiranite, Ferrium, Cuprium, and Dense Originium Powder is normal. <span class="mark-grey">In fact, from the time Xiranite/Cuprium still has stored reserves until the final steady state—Xiranite/Cuprium storage empty and Separator Core/Xircon storage full—the line provides the optimal Pyrrolite/Heavy Xiranite ratio for “total Xiranite/Cuprium produced during this period + Xiranite/Cuprium initially in storage.”</span> <span class="mark-grey"><u>In other words, provided storage is not full for everything, a warmed-up line is actually operating in its complete form all along.</u></span></p></li><li><p>Since, as above, Xiranite consumption exceeds production, its storage will eventually reach zero before any product storage fills. Is there a way to retain some Xiranite? See “Warm-Up” below: <a href="./page-umMgUzRULECbKVLsX5rOlZ#source-block-sdvd1X3RJrhAL32oIkexUc">1.5 Automatic Maximum Gross Production</a>.</p></li><li><p>If generation is no more than 9800 but you still suffer a major outage, with Cuprium storage full, the decoupling module has a problem. Most likely you lacked 500+ Jincao when placing the blueprint. Prepare enough Jincao and replace the main-base blueprints.</p></li><li><p>Pyrrolite production around 60/min most likely means Hetonite storage is not full. Our automatic switching produces Hetonite and Pyrrolite at 1:2 while Hetonite storage is not full. Leave it alone: Pyrrolite, Heavy Xiranite, and batteries easily redeem all vouchers. <span class="mark-grey">If you really do not want Hetonite, close the Hetonite Gas control port beside the crucible by enabling its passing-quantity limit at 1.</span></p></li><li><p>If Hetonite/Pyrrolite production drops sharply—halved or worse, though a smaller drop can also have this cause—check upstream of the North Wuling Exclusion Zone&#39;s Xiragen Conduit Outlet Manifold, namely the inlet connected to it. If it is a Conduit Inlet Manifold, use only one of its ports; keep the other free of Xiragen and merge Xiragen into just one port. Alternatively, replace it with a single-port Conduit Inlet. <u><strong>Another possibility:</strong></u> you simply have not connected 80 Xiragen from deposits. One high-purity gas vent supplies 20 and one low-purity deposit 10; do not connect too few. <u><strong>Yet another possibility:</strong></u> the Expanded Crucible has lost its Xiranite input oversupply. Replace the blueprint or see “Warm-Up”: <a href="./page-umMgUzRULECbKVLsX5rOlZ#source-block-sdvd1X3RJrhAL32oIkexUc">1.5 Automatic Maximum Gross Production</a>.</p></li><li><p>If Xiranite production does not reach 360, check that enough plants (Jincao) are placed in Jingyu Valley, Fluid Pumps are correctly connected, and Inergen is connected normally. Elevation differences can leave gas vents disconnected from conduits. If you move conduits elsewhere to connect them, return the connected conduits and manifolds to their original base positions. <span class="mark-grey">Check water piping: two conduit manifolds, each port of each manifold merging two Fluid Pumps, not three; a single-port conduit outside the base connects one Fluid Pump.</span> <span class="mark-red">If Jincao is insufficient, FAQ 6 is likely to occur later too; investigate it:</span> <a href="./page-umMgUzRULECbKVLsX5rOlZ">1.5 Automatic Maximum Gross Production</a>.</p></li><li><p>Yinglung Pass warms up slowly; this is normal, taking about 1–2h. To accelerate it, see “Warm-Up”: <a href="./page-umMgUzRULECbKVLsX5rOlZ#source-block-sdvd1X3RJrhAL32oIkexUc">1.5 Automatic Maximum Gross Production</a>.</p></li><li><p>After Pyrrolite storage has been full for a long time, over half an hour, selling Pyrrolite will not immediately restart Yinglung Pass production. Automatically clearing the self-locking state takes 10–20 minutes. No Pyrrolite output during that period is normal; do not panic.</p></li><li><p>If Cuprium production is only 390 although its storage is not full, check whether the single-port conduit and manifold leading to the Purification Node/Water Treatment Unit are swapped. Likewise, if all mining rigs are running but Cuprium production is below 510, check that Sewage is draining, Clean Water is supplied, and mining deposits have water.</p></li><li><p>No Hetonite-related output although Hetonite storage is not full: check the orientation of the Reactor Crucible near the Yinglung Pass PAC, and the orientation of the PAC itself.</p></li><li><p>Recheck water and acid pump connections and the conduits inside the Wuling main base. In particular, if Xircon output is not 81 with the Purification Node, or 75 without it, check the Sewage conduits. Ensure the Purification Node conduits match the video.</p></li><li><p>Xircon production is 0: first check Xiranite production. Zero Xiranite output prevents Xircon production; see 2 for troubleshooting. After ruling out issue 2, check Fluid Pump connections; do not miss the water inlet right in the riverbank corner.</p></li><li><p>Xircon production is 0–31: normal if battery storage is full. Otherwise inspect the main base&#39;s Xircon line; see “Warm-Up” for repairs.</p></li><li><p>Separator Core production fails to exceed consumption: provided Xiranite production is 360 and Cuprium production 510—otherwise investigate issues 2, 5, and 6—check the upstream Xiranite/Cuprium Depot Unloaders for any that never transport an item. If any exist, see “Warm-Up.” Check Inergen vent connections too; elevation differences may have left them disconnected.</p></li><li><p>Cuprium Powder consumption does not reach 360 despite abundant powder: normal if Pyrrolite storage is full. After ruling out issue 3, check the acid conduits feeding the Cuprium Solution line: the three acid conduits placed together in the Yinglung Pass base corner. Elevation differences may leave them disconnected, or they may be connected incorrectly to the separate single-acid-pump conduit. Each of these three must connect two acid pumps; check them individually. <span class="mark-grey">Cuprium Powder consumption of 300 strongly suggests an acid pump is missing or misconnected. Pay special attention if you see this.</span></p></li><li><p>It is normal for the Fluid-Gas Transmuting Unit on the Inergen-inlet side of the Wuling main base not to operate regularly. It starts automatically only when downstream lacks Xiragen and upstream has sufficient Liquid Xiranite. Leave it alone; trust the line&#39;s automatic control.</p></li></ol><p><span class="mark-grey">Congratulations on reading this far. You have surpassed 80% of the group members (≧∇≦)/ </span><span class="mark-grey"><s>(The percentage is not that low.)</s></span></p><p>For more principles, see adaptive devices <a href="./page-kXUgC0EOTqKh09bVHL9EPN">Some Simpler Adaptive Setups</a> and automatic production-line balancing (for now) <a href="./page-MSyCxO1yMtqlXdUCG6Utsc#source-block-JHB9yrgA7h2xtO0t0QlxBz">Explanation: Automatically Balanced Production Lines and Adaptive Devices</a>.</p><p><span class="mark-blue">Conditions for operation without Xiranite waste: Xiranflow Cloudseeder at Yinglung Pass receives at least 80 Xiragen/min; Xiranite production is at least 300/min (10 Forges of the Sky); Cuprium Ore production is at least 280/min. You do not need every deposit or maximum regional development.</span></p><p><span class="mark-blue">Whether the Purification Node is connected, whether Dense Originium Powder is transferred beyond storage capacity, and whether all Originium Ore deposits are maxed out do not affect automatic balancing without Xiranite waste. You must, however, produce enough batteries for power generation.</span></p><p>P.S. If you <u><strong>can</strong></u> reach 18 Pyrrolite Part (12 Pyrrolite Part and 6 Hetonite Part), 36 Heavy Xiranite, and 15 batteries, things are basically correct. <strong>This does not mean every other report is wrong.</strong> <span class="mark-grey">In fact, a correctly built line produces different, equally correct reports under different input and intermediate-product conditions.</span></p><p><img src="/endfield-logistics-wiki/logistics/src/assets/images/img-137aed48cee7f36b.q90-aca6a5ee9222b010.webp" alt="15 Automatic Maximum Gross Production"></p><p><span id="source-block-sdvd1X3RJrhAL32oIkexUc"></span></p><span class="logistics-source-anchor" id="暖机相关" aria-hidden="true"></span><h2 id="warm-up" tabindex="-1">Warm-Up <a class="header-anchor" href="#warm-up" aria-label="Permalink to &quot;Warm-Up&quot;">​</a></h2><p>Start this blueprint with some Xiranite in storage.<br> What if you do not have any?</p><p><img src="/endfield-logistics-wiki/logistics/src/assets/images/img-788d46ce6b993357.q90-3274c78a48a959d2.webp" alt="15 Automatic Maximum Gross Production"></p><p>Turn off the four crucibles shown above to accumulate some. Remember to turn them back on after warm-up. <span class="mark-blue">Of course, if you want to accumulate Xiranite in the depot, you can leave them off. For further uses, see “Independent Material Draws” below.</span> <a href="./page-umMgUzRULECbKVLsX5rOlZ#source-block-4KFSHVD7aAsnzKeVp1Dyo5">1.5 Automatic Maximum Gross Production</a><br><strong>Likewise, if Yinglung Pass&#39;s Expanded Crucible produces less than 60 Liquid Xiranite/min—not full-rate production—or the Packaging Unit making Separator Core lacks Xiranite, this resets the unloaders&#39; round-robin servicing. Similarly, if that Packaging Unit lacks Cuprium Canister, hence Cuprium, turn off a few Shredding Units in the main base&#39;s southeast corner to accumulate Cuprium and reset the unloaders&#39; round-robin servicing.</strong></p><p><span class="mark-red">What happens without Xiranite? There is a small chance insufficient Xiranite oversupply to the Separator Core/Xircon lines will break the Xircon line and disable automatic balancing (loss of oversupply to Separator Core). See the next image for Xircon-line repairs:</span></p><p><img src="/endfield-logistics-wiki/logistics/src/assets/images/img-6a8f7a49d718e711.q90-22e32aacb6cf6d33.webp" alt="15 Automatic Maximum Gross Production"></p><p>As for why, all I can say is that mysterious yj&#39;s mysterious unloader/loader priorities are doing their mysterious thing. We tried exploring the rules but got almost nowhere. For the 1.6 factory we will definitely use a solid-Xiranite bus starting at the Forge of the Sky (((</p><p>Yinglung also warms up slowly because its 2000 Liquid Xiranite buffer must fill. Do not worry; a slow start is normal. Wait-for-me-to-start.jpg I-have-started.jpg</p><p><span class="mark-blue">Of course, filling every Liquid Xiranite conduit in Yinglung with Liquid Xiranite completes the warm-up immediately.</span></p><p><span id="source-block-O9Y1NDa77n2YmO3RXdzq6a"></span></p><span class="logistics-source-anchor" id="自动赫灼恶性bug-已解决" aria-hidden="true"></span><h2 id="severe-automatic-hetonite-pyrrolite-switching-bug-resolved" tabindex="-1">Severe Automatic Hetonite/Pyrrolite Switching Bug (Resolved) <a class="header-anchor" href="#severe-automatic-hetonite-pyrrolite-switching-bug-resolved" aria-label="Permalink to &quot;Severe Automatic Hetonite/Pyrrolite Switching Bug (Resolved)&quot;">​</a></h2><p>While Cuprium/Cuprium Powder storage is not empty, the Pyrrolite/Hetonite line runs flat out, giving 30 Hetonite/min. Amusingly, Hetonite transport through the unpowered crucible and Item Control Port slows down offline. After roughly 8–12h offline, Hetonite fills the machine, though there is no problem online. See below; it does not even display a production-stop indicator.</p><p><img src="/endfield-logistics-wiki/logistics/src/assets/images/img-3d226a234f53ce5c.q90-e710c4b01eb4a878.webp" alt="15 Automatic Maximum Gross Production"></p><p>With 50 Hetonite in the machine, when the unpowered crucible cuts off Hetonite Gas, the amount of Hetonite flowing into and accumulating in that crucible is the machine&#39;s 50 Hetonite plus whatever the Hetonite Gas remaining in pipes and machines will produce. We designed the latter to be less than 100 Hetonite Gas, whose Hetonite output would not fill the unpowered crucible&#39;s buffer. Adding the machine&#39;s 50 Hetonite, however, makes it overflow and block the belt, preventing subsequently produced Pyrrolite from passing normally, as shown below:</p><p><img src="/endfield-logistics-wiki/logistics/src/assets/images/img-c2341731e9436b6a.q90-df53e542fc400244.webp" alt="15 Automatic Maximum Gross Production"></p><p><span class="mark-blue"><strong>Addendum: a permanent fix:</strong></span><br> A helpful bilibili user reminded me that it is hard to avoid accumulating Cuprium in practice: once either Heavy Xiranite or Pyrrolite storage fills, it accumulates. We therefore need a permanent solution: reduce the Hetonite flow through each crucible/control-port route.</p><p><s>By moving the conduit manifolds outside, we successfully found open space for modifications (a blatant lie), allowing two Hetonite inputs and two outputs on the unpowered crucible. Inelegant, but we really had no other ideas. (The Protocol Stash and multiple control ports are unnecessary; I just filled the available space to avoid any possible problems.)</s></p><p><span class="mark-blue"><strong>(2026.9.8) Updated Yinglung 01 and 03, completely eliminating the problem.</strong></span><span class="mark-yellow"><strong>(2026.9.10) (Because of unpredictable offline slowdowns, if Hetonite still blocks Pyrrolite after you modify everything correctly, send us an example. A simple fix is to remove Hetonite from the Solid-Gas Transmuting Unit and belt.) (After all that, it was still the control port slowing down. yj, I really have to get you under control; we are still fixing this!)</strong></span><span class="mark-red"><strong>(2026.9.15: Completely fixed; updated Yinglung 010203 blueprints.)</strong></span></p><p><img src="/endfield-logistics-wiki/logistics/src/assets/images/img-9522bfa425662ad8.q90-a33446ed3c321797.webp" alt="15 Automatic Maximum Gross Production"></p><p>The theory relating to output lag comes from <a href="./page-oWvEDex0yuejzwpcwzyxUP">Introduction to Analyzing Endfield Logistics Bugs</a>.</p><p><span id="source-block-b0yB7GcYPo8AVeFqRmsf5g"></span></p><span class="logistics-source-anchor" id="壤晶线应急修理办法" aria-hidden="true"></span><h2 id="emergency-xircon-line-repairs" tabindex="-1">Emergency Xircon-Line Repairs <a class="header-anchor" href="#emergency-xircon-line-repairs" aria-label="Permalink to &quot;Emergency Xircon-Line Repairs&quot;">​</a></h2><p>First try the methods in <a href="./page-umMgUzRULECbKVLsX5rOlZ#source-block-sdvd1X3RJrhAL32oIkexUc">1.5 Automatic Maximum Gross Production</a>, and make sure your Jingyu Valley uses the September 15 update <a href="./page-umMgUzRULECbKVLsX5rOlZ#source-block-qMT4GtWsR8rDPnonIh5VLq">1.5 Automatic Maximum Gross Production</a>. If those fail, apply these more drastic measures as well.</p><p><span id="source-block-WHfdcZtJSaRyhjr8nzKDuf"></span></p><span class="logistics-source-anchor" id="小幅降低电池产量" aria-hidden="true"></span><h3 id="slightly-reduce-battery-production" tabindex="-1">Slightly Reduce Battery Production <a class="header-anchor" href="#slightly-reduce-battery-production" aria-label="Permalink to &quot;Slightly Reduce Battery Production&quot;">​</a></h3><p><span class="mark-red">Requires full Xircon storage.</span></p><p>Reduce battery capacity to lower Xircon demand. Turn off the main-base battery line at the location shown:</p><p><img src="/endfield-logistics-wiki/logistics/src/assets/images/img-337f4c86b1bcc5c7.q90-665d8e059a5ded75.webp" alt="15 Automatic Maximum Gross Production"></p><p><span id="source-block-HWIfr9ISfbSyUfbmd7FxEQ"></span></p><span class="logistics-source-anchor" id="开启壤晶线自动销毁" aria-hidden="true"></span><h3 id="enable-automatic-destruction-on-the-xircon-line" tabindex="-1">Enable Automatic Destruction on the Xircon Line <a class="header-anchor" href="#enable-automatic-destruction-on-the-xircon-line" aria-label="Permalink to &quot;Enable Automatic Destruction on the Xircon Line&quot;">​</a></h3><p>The cost is wasting some inputs after Xircon storage fills. Enable destruction in the Expanded Crucibles shown:</p><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td><img src="/endfield-logistics-wiki/logistics/src/assets/images/img-2323ce0c5825a2e4.q90-a178f576f8c0d3f4.webp" alt="Image"></td><td><img src="/endfield-logistics-wiki/logistics/src/assets/images/img-ae3a1f06ca42a124.q90-6bbd7dc496d4cd36.webp" alt="Image"></td></tr></tbody></table><p><span id="source-block-4KFSHVD7aAsnzKeVp1Dyo5"></span></p><span class="logistics-source-anchor" id="自由调用" aria-hidden="true"></span><h2 id="independent-material-draws" tabindex="-1">Independent Material Draws <a class="header-anchor" href="#independent-material-draws" aria-label="Permalink to &quot;Independent Material Draws&quot;">​</a></h2><p><span id="source-block-J3tMFGGo6XhWKpyc5VQzKj"></span></p><span class="logistics-source-anchor" id="自由地新增取货口" aria-hidden="true"></span><h3 id="freely-add-depot-unloaders" tabindex="-1">Freely Add Depot Unloaders <a class="header-anchor" href="#freely-add-depot-unloaders" aria-label="Permalink to &quot;Freely Add Depot Unloaders&quot;">​</a></h3><p><img src="/endfield-logistics-wiki/logistics/src/assets/images/img-65ca1fd3aabbf9fc.q90-e7a48528efe2258b.webp" alt="15 Automatic Maximum Gross Production"></p><p>Just add them. Allowed materials are Cuprium, Xiranite, Heavy Xiranite, Hetonite, and Pyrrolite. To keep it simple, use no more than two ports per material. <span class="mark-grey">Do not copy the Originium Ore shown in the picture, unless you open only one or two ports like me; too many might cause a power outage. For Ferrium, turn off the small medicine (blue-quality Yazhen Syringe [C]) and open one or two ports. More can affect Xircon.</span></p><p>How do you tell if you have added too many? See the next subsection.</p><p><span id="source-block-gej0LiIH7rHaM0Vt2wX0oT"></span></p><span class="logistics-source-anchor" id="对已有产线影响" aria-hidden="true"></span><h3 id="effects-on-existing-lines" tabindex="-1">Effects on Existing Lines <a class="header-anchor" href="#effects-on-existing-lines" aria-label="Permalink to &quot;Effects on Existing Lines&quot;">​</a></h3><p>Too many additional unloaders may starve the Xircon line of Xiranite, and the Separator Core line of Xiranite/Cuprium, with undesirable results. Check whether stored Separator Core and Xircon quantities decline. If neither declines, there is no problem.</p><p>Take the next image as an example: no final product storage is full; Xiranite storage is empty but Cuprium storage is not. Xircon production exceeds consumption, so its stored amount is not declining. Separator Core production equals consumption and maintains full storage, so that stored amount is not declining either. This player&#39;s independent draws are therefore fine.</p><p><img src="/endfield-logistics-wiki/logistics/src/assets/images/img-77d45137a2e671ea.q90-a16e66dcb06a60b3.webp" alt="15 Automatic Maximum Gross Production"></p><p>If Xircon/Separator Core reserves decline, is reducing the number of unloaders the only option? See the next subsection.</p><p><span id="source-block-6rcRwbuFHgJ50Hq0nLJmk8"></span></p><span class="logistics-source-anchor" id="扩大自由调用区间" aria-hidden="true"></span><h3 id="expand-the-range-available-for-independent-draws" tabindex="-1">Expand the Range Available for Independent Draws <a class="header-anchor" href="#expand-the-range-available-for-independent-draws" aria-label="Permalink to &quot;Expand the Range Available for Independent Draws&quot;">​</a></h3><p><img src="/endfield-logistics-wiki/logistics/src/assets/images/img-b4d2cacf59cf4d37.q90-ac51b31783a3d084.webp" alt="15 Automatic Maximum Gross Production"></p><p>After switching these off, use the same test for excessive independent draws: verify that Xircon/Separator Core reserves do not decline.</p><p><span id="source-block-yPXXfFf7EL6X4QwKtZP7E6"></span></p><span class="logistics-source-anchor" id="加压输入以达到满速。" aria-hidden="true"></span><h3 id="oversupply-inputs-to-reach-full-rate" tabindex="-1">Oversupply Inputs to Reach Full Rate <a class="header-anchor" href="#oversupply-inputs-to-reach-full-rate" aria-label="Permalink to &quot;Oversupply Inputs to Reach Full Rate&quot;">​</a></h3><p>Connect more unloaders to the same belt/machine to ensure it receives enough material even with empty depot storage.</p><p><img src="/endfield-logistics-wiki/logistics/src/assets/images/img-6a74c5864eabf1f2.q90-f25397b2cd725d46.webp" alt="15 Automatic Maximum Gross Production"></p><p>Note that a Converger placed flush against an unloader exhibits priority behavior. Avoid this when your goal is oversupply.</p><p><span id="source-block-2keVNLDdBAsIkkMmbc6A8b"></span></p><span class="logistics-source-anchor" id="_1-5智能最大毛产-1" aria-hidden="true"></span><span class="logistics-source-anchor" id="manually-switch-to-all-pyrrolite" aria-hidden="true"></span><span class="logistics-source-anchor" id="手切全灼铜" aria-hidden="true"></span><h3 id="_1-5-automatic-maximum-gross-production-1" tabindex="-1"><a href="./page-umMgUzRULECbKVLsX5rOlZ">1.5 Automatic Maximum Gross Production</a> <a class="header-anchor" href="#_1-5-automatic-maximum-gross-production-1" aria-label="Permalink to &quot;[1.5 Automatic Maximum Gross Production](page-umMgUzRULECbKVLsX5rOlZ.md)&quot;">​</a></h3><p><span id="source-block-yDHClNwcDGibbpxhXKAypZ"></span></p><span class="logistics-source-anchor" id="手切三核赫铜模式" aria-hidden="true"></span><h3 id="manually-switch-to-three-core-hetonite-mode" tabindex="-1">Manually Switch to Three-Core Hetonite Mode <a class="header-anchor" href="#manually-switch-to-three-core-hetonite-mode" aria-label="Permalink to &quot;Manually Switch to Three-Core Hetonite Mode&quot;">​</a></h3><p>First find the two Conduit Outlets and control ports shown:</p><p><img src="/endfield-logistics-wiki/logistics/src/assets/images/img-03e6aa9080d58e6b.q90-4acd7f671c296549.webp" alt="15 Automatic Maximum Gross Production"></p><p>Now swap the two outlets as shown:</p><p><img src="/endfield-logistics-wiki/logistics/src/assets/images/img-636e418498fae49c.q90-d35d20fa6886dd88.webp" alt="15 Automatic Maximum Gross Production"></p><p>When you restore them—returning to Pyrrolite solidification, as in the first image—you must also clear the remaining Hetonite Gas from the Solid-Gas Transmuting Unit.</p><p><img src="/endfield-logistics-wiki/logistics/src/assets/images/img-727b58ca5ab35609.q90-b5cc6cc105ecbd4f.webp" alt="15 Automatic Maximum Gross Production"></p><p><span id="source-block-qCgclCgP4EeJ8NQPctqHLi"></span></p><span class="logistics-source-anchor" id="全物品" aria-hidden="true"></span><h3 id="all-items" tabindex="-1">All Items!? <a class="header-anchor" href="#all-items" aria-label="Permalink to &quot;All Items!?&quot;">​</a></h3><p><a href="./page-pRYbuAlRWdRJutvUjeqpKw">1.5 Automatic All-Item Production</a></p><p><span id="source-block-kK6NOYj9oOxPhfdKLYWdO5"></span></p><span class="logistics-source-anchor" id="蓝图更新日志" aria-hidden="true"></span><h2 id="blueprint-update-log" tabindex="-1">Blueprint Update Log <a class="header-anchor" href="#blueprint-update-log" aria-label="Permalink to &quot;Blueprint Update Log&quot;">​</a></h2><p><span id="source-block-SK1GdKSwVckcaqxIeryCmX"></span></p><h3 id="_2026-9-7-13-49" tabindex="-1">2026.9.7 13:49 <a class="header-anchor" href="#_2026-9-7-13-49" aria-label="Permalink to &quot;2026.9.7 13:49&quot;">​</a></h3><p><img src="/endfield-logistics-wiki/logistics/src/assets/images/img-8d5160886fef8857.q90-927b88c00412452c.webp" alt="15 Automatic Maximum Gross Production"></p><p><span id="source-block-eGjXf3am8qXHkuk54zaVaZ"></span></p><span class="logistics-source-anchor" id="_2026-9-8-00-26-无效更新" aria-hidden="true"></span><h3 id="_2026-9-8-00-26-ineffective-update" tabindex="-1">2026.9.8 00:26<span class="mark-red"> (Ineffective Update)</span> <a class="header-anchor" href="#_2026-9-8-00-26-ineffective-update" aria-label="Permalink to &quot;2026.9.8 00:26&lt;span class=&quot;mark-red&quot;&gt; (Ineffective Update)&lt;/span&gt;&quot;">​</a></h3><p>An unsuccessful fix for automatic Hetonite/Pyrrolite switching. We misidentified the unpowered crucible as the cause of offline slowdown; the Item Control Port was actually responsible.</p><p>Testing offline slowdown takes a very long time. I am deeply sorry for the impact of the delayed update.</p><p><span id="source-block-LFNyZ7wjTCsoYzDyBHqeUv"></span></p><h3 id="_2026-9-15-2-56" tabindex="-1">2026.9.15 2:56 <a class="header-anchor" href="#_2026-9-15-2-56" aria-label="Permalink to &quot;2026.9.15 2:56&quot;">​</a></h3><p>Rebuilt the entire Yinglung base to fix the automatic Hetonite/Pyrrolite bug. Follow the conduits&#39; connection process in the video, moving each externally connected conduit out of the base. Delete the old Yinglung base and place the blueprints again, starting with preparation of the unpowered crucible. Do not keep the old unpowered crucible: prepare it again to avoid errors in preserving it. Blueprint codes: <a href="./page-umMgUzRULECbKVLsX5rOlZ#source-block-aZli93Lno95jxDGgn1OJj9">1.5 Automatic Maximum Gross Production</a>.<br> Before replacing, ensure 500+ Xiranite in storage, with neither Hetonite nor Pyrrolite storage full. If you have no Xiranite, follow <a href="./page-umMgUzRULECbKVLsX5rOlZ#source-block-sdvd1X3RJrhAL32oIkexUc">1.5 Automatic Maximum Gross Production</a>. If Hetonite and Pyrrolite storage are full, consume 500+ Hetonite Part and Pyrrolite Part.</p><p><span id="source-block-wb2utUlRz6aEWq0fE41u0Z"></span></p><h3 id="_2026-9-16-0-57" tabindex="-1">2026.9.16 0:57 <a class="header-anchor" href="#_2026-9-16-0-57" aria-label="Permalink to &quot;2026.9.16 0:57&quot;">​</a></h3><p>Rebuilt the entire Jingyu Valley base to greatly reduce the likelihood of various failures to maintain Xiranite oversupply. Essentially, some Xiranite was previously deposited through Depot Loaders and now passes through stashes, allowing mostly round-robin unloader servicing to maintain oversupply. Water/Inergen now use exposed inlet pipes, reducing copying mistakes. Blueprint codes: <a href="./page-umMgUzRULECbKVLsX5rOlZ#source-block-qMT4GtWsR8rDPnonIh5VLq">1.5 Automatic Maximum Gross Production</a>.</p><p>Before replacing, ensure 500+ Jincao and Sandleaf Seed, plus 1000+ Xiranite, to prevent the Xircon line from breaking due to Xiranite starvation during reconstruction. If Xiranite storage is exhausted, see <a href="./page-umMgUzRULECbKVLsX5rOlZ#source-block-sdvd1X3RJrhAL32oIkexUc">1.5 Automatic Maximum Gross Production</a>. If you really do not want to prepare Xiranite reserves, you can let the Xircon line break, rebuild Jingyu, and then fix the line according to <a href="./page-umMgUzRULECbKVLsX5rOlZ#source-block-sdvd1X3RJrhAL32oIkexUc">1.5 Automatic Maximum Gross Production</a>. That also works.</p><p><span id="source-block-lD4jP6Jb5YIJHyAQt21JkC"></span></p><h3 id="_2026-9-21" tabindex="-1">2026.9.21 <a class="header-anchor" href="#_2026-9-21" aria-label="Permalink to &quot;2026.9.21&quot;">​</a></h3><p>Fixed blueprint problems caused by incorrect phase-two Chubby Lung recipes and ratio calculations.</p><p><span id="source-block-PKgviX9HsEAEEJnxfTwyiO"></span></p><span class="logistics-source-anchor" id="性能简述" aria-hidden="true"></span><h2 id="performance-overview" tabindex="-1">Performance Overview <a class="header-anchor" href="#performance-overview" aria-label="Permalink to &quot;Performance Overview&quot;">​</a></h2><p>All capacities below assume you have not added other lines yourself.</p><p>Capacity conditions: Originium Ore 540/min, Ferrium Ore 120/min, Cuprium Ore 510/min, Xiragen 150/min; Dense Originium Powder transferred beyond storage capacity; Purification Node connected; Yinglung Pass Xiragen conduit connected to the main base. <span class="mark-blue">Cuprium and Xiranite storage are both empty; Xircon and Separator Core storage are both full.</span> All numbers below are in unit/min:</p><p>Hetonite storage not full: 34.845(54219/1556) Heavy Xiranite, 11.277(17547/1556) Pyrrolite Part, 5.6385(17547/3112) Hetonite Part, 14.75 SC Wuling Battery, 2.3125 Yazhen Syringe [C], 0 Xiranite, 0 Cuprium Ore, 0 Originium Ore, 0 Dense Originium Powder, 0 Ferrium Ore.</p><p>Hetonite storage full: 28.705(28734/1001) Heavy Xiranite, 17.529(17547/1001) Pyrrolite Part, 0 Hetonite Part, 14.75 SC Wuling Battery, 2.3125 Yazhen Syringe [C], 0 Xiranite, 0 Cuprium Ore, 0 Originium Ore, 0 Dense Originium Powder, 0 Ferrium Ore. (Gross voucher output 2836.5, or 4.08 million Wuling Stock Bills (408w; w means 10,000) per day.)</p><p>(The following all assume full Hetonite storage. With SC Wuling Battery storage full, 4.5/min batteries are consumed to generate 9600 power.)</p><p>SC Wuling Battery storage full: 36 Heavy Xiranite, 16.8 Pyrrolite Part, 0 Hetonite Part, 4.5 SC Wuling Battery, 3 Yazhen Syringe [C], 33.32 Xiranite, 0 Cuprium Ore, 360 Originium Ore, 25 Dense Originium Powder, 37.5 Ferrium Ore.</p><p>Pyrrolite storage full: 36 Heavy Xiranite, 0 Pyrrolite Part, 0 Hetonite Part, 14.75 SC Wuling Battery, 2.3125 Yazhen Syringe [C], 127.4 Xiranite, 420 Cuprium Ore, 0 Originium Ore, 0 Dense Originium Powder, 0 Ferrium Ore.</p><p>Heavy Xiranite storage full: 0 Heavy Xiranite, 18 Pyrrolite Part, 0 Hetonite Part, 14.75 SC Wuling Battery, 2.3125 Yazhen Syringe [C], 198.2 Xiranite, 60 Cuprium Ore, 0 Originium Ore, 0 Dense Originium Powder, 0 Ferrium Ore.</p><p>Automatically converges to the optimal Pyrrolite Part/Heavy Xiranite ratio; automatically switches between Hetonite and Pyrrolite without manually clearing the furnace; allows additional Xiranite/Cuprium/Originium Ore unloaders while still balancing remaining inputs; balances regardless of Purification Node connection, maximum regional development, all map deposits being opened, or Dense Originium Powder transfer beyond storage capacity; accelerates other lines when one final product fills storage, without destroying high-value final products; supports Integrated Aid Chubby Lung.</p><p>Steady states with absolutely no Xiranite waste:</p><p>① No product storage full. ② Only Hetonite storage full. ③ Only SC Wuling Battery storage full. ④ All-Hetonite mode with neither Hetonite nor Heavy Xiranite storage full; SC Wuling Battery storage may also be full.</p><p>Other steady states have extremely slight Xiranite waste. In practice, a more likely form of Xiranite waste in those “other steady states” is simply filling all 90,000 Xiranite storage (9w), as the production tables above show, so there is no need to worry.</p><p>Maximum Cuprium/Xiranite draws supported without modifying the lines while ensuring maximum battery output:</p><p>83.181 Xiranite, 237.10 Cuprium Ore.</p><p>If line modifications are allowed: 510 Cuprium Ore and 251.6 Xiranite (i.e. after subtracting the 108.4 Xiranite used by 14.75 batteries).</p><blockquote><p>Translation note: The source’s w notation means ten thousand. Source arithmetic, dated updates and blueprint codes are retained; localized names do not update historical game claims.</p></blockquote></div>',1)])])}const m=i(n,[["render",o]]);export{h as __pageData,m as default};
